        "title": "Entrepreneurship | Business | Startup Culture on Instagram: \"Life throws punches, but we keep moving forward together still.\n\nMike Tyson Quote is a Wake up Call Everyone has a plan until the first punch lands, and life doesn&#x2019;t care about our schedules. You set goals, you rehearse answers for interviews, you swipe right hoping for a date, you invest hoping for returns. Then reality hits a missed job, a silent match, a market dip and suddenly the blueprint feels useless.\n\nThe real test isn&#x2019;t avoiding the blow, but staying focused on the next move. When the bell rings again, you step back into the ring, adjust your stance, and keep fighting. That step forward, even after a hit, is what separates those who survive from those who quit.\n\nFollow &#064;entreprefy for more &#x1f91d;\"",
        "creator": "Instagram",
        "topic": "Motivation",
        "thumbnailUrl": "https://scontent.cdninstagram.com/v/t51.71878-15/628737138_2615524622154109_4779005985418350164_n.jpg?stp=cmp1_dst-jpg_e35_s640x640_tt6&_nc_cat=100&ccb=7-5&_nc_sid=18de74&efg=eyJlZmdfdGFnIjoiQ0xJUFMuYmVzdF9pbWFnZV91cmxnZW4uQzMifQ%3D%3D&_nc_ohc=ZKhYIASBBFQQ7kNvwE_SN8M&_nc_oc=AdrsFBNiMQsBDwn-x8bIVfhVtoKen62hG3EQthPZBDiopTX2IP2LpPeri_JMcvZ9TWo&_nc_zt=23&_nc_ht=scontent.cdninstagram.com&_nc_gid=fG3ohTXZC6N4QnUTZI13nw&_nc_ss=7c689&_nc_ct=RQosPBUKFQQAAAA&oh=00_AQS_LchCPvlFPlX2vle6Zu4Dh0kCPA4LT9feSg1Px9rQAg&oe=6B093EF4"
